 return f'''<!doctype html><html lang="en-CA"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)}</title><meta name="description" content="{E(description,quote=True)}"><meta name="robots" content="{'noindex,nofollow' if demo else 'index,follow,max-image-preview:large'}"><link rel="canonical" href="https://jowkaritech.com/{path}"><meta name="theme-color" content="#f6f3ec"><link rel="icon" href="/JowkariTech%20logo.png"><meta property="og:type" content="website"><meta property="og:title" content="{E(title)}"><meta property="og:description" content="{E(description,quote=True)}"><meta property="og:url" content="https://jowkaritech.com/{path}"><meta property="og:image" content="https://jowkaritech.com/assets/site/roofing-preview.webp"><link rel="stylesheet" href="/assets/site/design.css?v=editorial-1"><script type="application/ld+json">{json.dumps(schema)}</script><script src="/assets/site/site.js?v=editorial-1" defer></script></head><body class="{body_class}"><a class="skip" href="#main">Skip to content</a>'''

